<?php
require_once 'app_bootstrap.php';require_once 'db.php';require_once 'security.php';
if(!customer_is_logged_in())redirect_with_message('reglog.php','Please sign in to view your profile.');
try{$db=db_connect();}catch(Throwable $error){redirect_with_message('reglog.php','Your profile is temporarily unavailable.');}
$email=$_SESSION['user_email'];
function remove_profile_file(?string $path):void{if(!$path||!str_starts_with($path,'uploads/profile/'))return;$full=__DIR__.'/'.$path;if(is_file($full))@unlink($full);}
function age_from_dob(?string $dob):?int{if(!$dob)return null;try{$birth=new DateTimeImmutable($dob);$today=new DateTimeImmutable('today');return $birth>$today?null:$birth->diff($today)->y;}catch(Throwable $error){return null;}}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 if($action==='details'){$name=trim($_POST['name']??'');$phone=trim($_POST['phone']??'');$alt=trim($_POST['alt_phone']??'');$dob=trim($_POST['date_of_birth']??'')?:null;$gender=trim($_POST['gender']??'');$address=trim($_POST['address']??'');$city=trim($_POST['city']??'');$state=trim($_POST['state']??'');$postal=trim($_POST['postal_code']??'');$medical=trim($_POST['medical_issues']??'');$isPwd=!empty($_POST['is_pwd'])?1:0;$pwdDetails=$isPwd?trim($_POST['pwd_details']??''):'';if($name===''||($phone!==''&&!preg_match('/^[0-9]{10}$/',$phone))||($alt!==''&&!preg_match('/^[0-9]{10}$/',$alt))||($dob!==null&&$dob>date('Y-m-d'))||!in_array($gender,['','Female','Male','Other','Prefer not to say'],true)||strlen($pwdDetails)>500)redirect_with_message('profile.php','Enter valid personal details and phone numbers.');$country='India';$s=$db->prepare('UPDATE users SET name=?,phone=?,alt_phone=?,date_of_birth=?,gender=?,address=?,city=?,state=?,postal_code=?,country=?,medical_issues=?,is_pwd=?,pwd_details=? WHERE email=?');$s->bind_param('sssssssssssiss',$name,$phone,$alt,$dob,$gender,$address,$city,$state,$postal,$country,$medical,$isPwd,$pwdDetails,$email);$s->execute();$_SESSION['login']=$name;redirect_with_message('profile.php','Personal and travel details updated.');}
 if($action==='upload_photo'){if(empty($_FILES['profile_image'])||$_FILES['profile_image']['error']!==UPLOAD_ERR_OK)redirect_with_message('profile.php','Choose an image to upload.');$file=$_FILES['profile_image'];if($file['size']>3*1024*1024)redirect_with_message('profile.php','Profile image must be smaller than 3 MB.');$imageInfo=@getimagesize($file['tmp_name']);$mime=class_exists('finfo')?(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']):($imageInfo['mime']??'');$types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($types[$mime])||!$imageInfo)redirect_with_message('profile.php','Upload a valid JPG, PNG, or WebP image.');$directory=__DIR__.'/uploads/profile';if(!is_dir($directory)&&!mkdir($directory,0755,true))redirect_with_message('profile.php','The profile upload directory is not writable.');$relative='uploads/profile/'.hash_file('sha256',$file['tmp_name']).'.'.$types[$mime];if(!is_file(__DIR__.'/'.$relative)&&!move_uploaded_file($file['tmp_name'],__DIR__.'/'.$relative))redirect_with_message('profile.php','The image could not be saved.');$s=$db->prepare('SELECT profile_image FROM users WHERE email=?');$s->bind_param('s',$email);$s->execute();$old=$s->get_result()->fetch_assoc()['profile_image']??null;$s=$db->prepare('UPDATE users SET profile_image=? WHERE email=?');$s->bind_param('ss',$relative,$email);$s->execute();if($old!==$relative)remove_profile_file($old);redirect_with_message('profile.php','Profile image updated.');}
 if($action==='remove_photo'){$s=$db->prepare('SELECT profile_image FROM users WHERE email=?');$s->bind_param('s',$email);$s->execute();$old=$s->get_result()->fetch_assoc()['profile_image']??null;$s=$db->prepare('UPDATE users SET profile_image=NULL WHERE email=?');$s->bind_param('s',$email);$s->execute();remove_profile_file($old);redirect_with_message('profile.php','Profile image removed.');}
 if($action==='add_family'){$name=trim($_POST['family_name']??'');$relationship=trim($_POST['relationship']??'');$dob=$_POST['date_of_birth']?:null;$gender=trim($_POST['gender']??'');$phone=trim($_POST['family_phone']??'');$medical=trim($_POST['family_medical']??'');$isPwd=!empty($_POST['is_pwd'])?1:0;$pwdDetails=$isPwd?trim($_POST['pwd_details']??''):'';if($name===''||$relationship===''||strlen($pwdDetails)>500)redirect_with_message('profile.php','Family member name and relationship are required.');$s=$db->prepare('INSERT INTO family_members(user_email,name,relationship,date_of_birth,gender,phone,medical_issues,is_pwd,pwd_details) VALUES(?,?,?,?,?,?,?,?,?)');$s->bind_param('sssssssis',$email,$name,$relationship,$dob,$gender,$phone,$medical,$isPwd,$pwdDetails);$s->execute();redirect_with_message('profile.php','Family member added.');}
 if($action==='edit_family'){$id=(int)($_POST['family_id']??0);$name=trim($_POST['family_name']??'');$relationship=trim($_POST['relationship']??'');$dob=trim($_POST['date_of_birth']??'')?:null;$gender=trim($_POST['gender']??'');$phone=trim($_POST['family_phone']??'');$medical=trim($_POST['family_medical']??'');$isPwd=!empty($_POST['is_pwd'])?1:0;$pwdDetails=$isPwd?trim($_POST['pwd_details']??''):'';if($id<1||$name===''||$relationship===''||($phone!==''&&!preg_match('/^[0-9]{10}$/',$phone))||($dob!==null&&$dob>date('Y-m-d'))||!in_array($gender,['','Female','Male','Other'],true)||strlen($pwdDetails)>500)redirect_with_message('profile.php#family-members','Enter valid family member details.');$s=$db->prepare('UPDATE family_members SET name=?,relationship=?,date_of_birth=?,gender=?,phone=?,medical_issues=?,is_pwd=?,pwd_details=? WHERE id=? AND user_email=?');$s->bind_param('ssssssisis',$name,$relationship,$dob,$gender,$phone,$medical,$isPwd,$pwdDetails,$id,$email);$s->execute();redirect_with_message('profile.php#family-members',$s->affected_rows?'Family member updated.':'No family member changes were required.');}
 if($action==='delete_family'){$id=(int)($_POST['family_id']??0);$s=$db->prepare('DELETE FROM family_members WHERE id=? AND user_email=?');$s->bind_param('is',$id,$email);$s->execute();redirect_with_message('profile.php','Family member removed.');}
 if($action==='password'){$current=$_POST['current_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';$s=$db->prepare('SELECT password FROM users WHERE email=?');$s->bind_param('s',$email);$s->execute();$stored=$s->get_result()->fetch_assoc()['password']??'';if(!password_verify($current,$stored)&&!hash_equals($stored,md5($current)))redirect_with_message('profile.php','Current password is incorrect.');if(strlen($new)<8||$new!==$confirm)redirect_with_message('profile.php','New passwords must match and contain at least 8 characters.');$hash=password_hash($new,PASSWORD_DEFAULT);$s=$db->prepare('UPDATE users SET password=? WHERE email=?');$s->bind_param('ss',$hash,$email);$s->execute();redirect_with_message('profile.php','Password changed successfully.');}
}
$s=$db->prepare('SELECT * FROM users WHERE email=?');$s->bind_param('s',$email);$s->execute();$user=$s->get_result()->fetch_assoc();if(!$user){session_destroy();header('Location:reglog.php');exit;}$family=[];$s=$db->prepare('SELECT * FROM family_members WHERE user_email=? ORDER BY created_at');$s->bind_param('s',$email);$s->execute();$result=$s->get_result();while($row=$result->fetch_assoc())$family[]=$row;
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Profile | Travel India</title><link rel="icon" href="img/favicon.jpg?v=1"><link rel="stylesheet" href="css/portal.css?v=8"><script src="js/password-toggle.js" defer></script></head><body class="profile-body"><?php include 'header.php';?>
<main class="portal-page profile-page"><header class="portal-heading"><div><span>Traveller profile</span><h1>My Profile</h1><p>Manage personal, medical, and family traveller details.</p></div><a class="portal-button" href="my-bookings.php">My Trips</a></header>
<section class="profile-hero"><div class="profile-photo"><?php if($user['profile_image']):?><img src="<?php echo e($user['profile_image']);?>" alt="<?php echo e($user['name']);?> profile photo"><?php else:?><span><?php echo e(strtoupper(substr($user['name'],0,1)));?></span><?php endif;?></div><div class="profile-identity"><h2><?php echo e($user['name']);?></h2><p><?php echo e($user['email']);?></p><span>Member since <?php echo e(date('F Y',strtotime($user['created_at'])));?></span><div class="photo-actions"><form method="post" enctype="multipart/form-data"><?php echo csrf_input();?><input type="hidden" name="action" value="upload_photo"><label class="portal-button">Choose photo<input type="file" name="profile_image" accept="image/jpeg,image/png,image/webp" required onchange="this.form.submit()"></label></form><?php if($user['profile_image']):?><form method="post" onsubmit="return confirm('Remove your profile photo?')"><?php echo csrf_input();?><input type="hidden" name="action" value="remove_photo"><button class="text-button">Remove photo</button></form><?php endif;?></div></div></section>
<div class="profile-forms"><section class="profile-panel"><h2>Personal details</h2><form method="post" class="profile-form"><?php echo csrf_input();?><input type="hidden" name="action" value="details"><label>Full name<input name="name" value="<?php echo e($user['name']);?>" required></label><label>Email<input value="<?php echo e($user['email']);?>" disabled></label><div class="form-pair"><label>Phone<input name="phone" pattern="[0-9]{10}" value="<?php echo e($user['phone']);?>"></label><label>Alternative phone<input name="alt_phone" pattern="[0-9]{10}" value="<?php echo e($user['alt_phone']);?>"></label></div><div class="form-pair"><label>Date of birth<input type="date" name="date_of_birth" max="<?php echo date('Y-m-d');?>" value="<?php echo e($user['date_of_birth']);?>"></label><label>Gender<select name="gender"><option value="">Prefer not to say</option><?php foreach(['Female','Male','Other','Prefer not to say'] as $gender):?><option <?php echo ($user['gender']??'')===$gender?'selected':'';?>><?php echo $gender;?></option><?php endforeach;?></select></label></div><label>Address<input name="address" value="<?php echo e($user['address']);?>"></label><div class="form-pair"><label>City<input name="city" value="<?php echo e($user['city']);?>"></label><label>State<input name="state" value="<?php echo e($user['state']);?>"></label></div><div class="form-pair"><label>Postal code<input name="postal_code" value="<?php echo e($user['postal_code']);?>"></label><label>Country<input value="India" disabled></label></div><label>Medical issues or accessibility needs<textarea name="medical_issues" rows="4" placeholder="Optional. Add information relevant to travel arrangements."><?php echo e($user['medical_issues']);?></textarea></label><label><span><input type="checkbox" name="is_pwd" value="1" <?php echo !empty($user['is_pwd'])?'checked':'';?>> Person with disability (PWD)</span></label><label>PWD support details<textarea name="pwd_details" rows="3" maxlength="500"><?php echo e($user['pwd_details']??'');?></textarea></label><button>Save profile</button></form></section>
<section class="profile-panel"><h2>Account security</h2><form method="post" class="profile-form"><?php echo csrf_input();?><input type="hidden" name="action" value="password"><?php foreach([['current_password','Current password'],['new_password','New password'],['confirm_password','Confirm new password']] as [$id,$label]):?><label><?php echo $label;?><span class="profile-password"><input id="<?php echo $id;?>" type="password" name="<?php echo $id;?>" minlength="<?php echo $id==='current_password'?1:8;?>" required><button type="button" data-password-toggle="<?php echo $id;?>" aria-label="Show password"><i class="fa-solid fa-eye"></i></button></span></label><?php endforeach;?><button>Change password</button></form></section></div>
<section class="family-section" id="family-members">
 <div class="section-heading"><div><span>Optional travellers</span><h2>Family Members</h2></div></div>
 <div class="family-layout"><div class="family-list">
 <?php if(!$family):?><div class="empty-state"><h3>No family members added</h3><p>Add people you commonly travel with. You can select them while booking.</p></div><?php endif;?>
 <?php foreach($family as $member):$memberAge=age_from_dob($member['date_of_birth']);?><article class="family-card"><div class="family-initial"><?php echo e(strtoupper(substr($member['name'],0,1)));?></div><div><h3><?php echo e($member['name']);?></h3><p><?php echo e($member['relationship']);?><?php echo $memberAge!==null?' · '.(int)$memberAge.' years old':'';?><?php echo $member['date_of_birth']?' · Born '.e(date('d M Y',strtotime($member['date_of_birth']))):'';?></p><?php if($member['medical_issues']):?><small><?php echo e($member['medical_issues']);?></small><?php endif;?></div><div class="family-actions"><button type="button" class="icon-edit family-edit" title="Edit family member" aria-label="Edit <?php echo e($member['name']);?>" data-id="<?php echo (int)$member['id'];?>" data-name="<?php echo e($member['name']);?>" data-relationship="<?php echo e($member['relationship']);?>" data-dob="<?php echo e($member['date_of_birth']);?>" data-gender="<?php echo e($member['gender']);?>" data-phone="<?php echo e($member['phone']);?>" data-medical="<?php echo e($member['medical_issues']);?>" data-is-pwd="<?php echo !empty($member['is_pwd'])?'1':'0';?>" data-pwd-details="<?php echo e($member['pwd_details']??'');?>"><i class="fa-solid fa-pen"></i></button><form method="post" onsubmit="return confirm('Remove this family member?')"><?php echo csrf_input();?><input type="hidden" name="action" value="delete_family"><input type="hidden" name="family_id" value="<?php echo (int)$member['id'];?>"><button class="icon-delete" title="Delete family member" aria-label="Delete <?php echo e($member['name']);?>"><i class="fa-solid fa-trash"></i></button></form></div></article><?php endforeach;?>
 </div><section class="profile-panel"><h2>Add family member</h2><form method="post" class="profile-form"><?php echo csrf_input();?><input type="hidden" name="action" value="add_family"><label>Name<input name="family_name" required></label><div class="form-pair"><label>Relationship<input name="relationship" placeholder="Spouse, parent, child..." required></label><label>Date of birth<input type="date" name="date_of_birth" max="<?php echo date('Y-m-d');?>"></label></div><div class="form-pair"><label>Gender<select name="gender"><option value="">Prefer not to say</option><option>Female</option><option>Male</option><option>Other</option></select></label><label>Phone<input name="family_phone" pattern="[0-9]{10}"></label></div><label>Medical issues or assistance<textarea name="family_medical" rows="3"></textarea></label><label><span><input type="checkbox" name="is_pwd" value="1"> Person with disability (PWD)</span></label><label>PWD support details<textarea name="pwd_details" rows="2" maxlength="500"></textarea></label><button>Add family member</button></form></section></div>
</section>
<dialog class="profile-dialog" id="family-edit-dialog"><div class="profile-dialog-head"><div><span>Optional traveller</span><h2>Edit family member</h2></div><button type="button" class="profile-dialog-close" aria-label="Close"><i class="fa-solid fa-xmark"></i></button></div><form method="post" class="profile-form profile-dialog-form"><?php echo csrf_input();?><input type="hidden" name="action" value="edit_family"><input type="hidden" name="family_id" id="edit-family-id"><label>Name<input name="family_name" id="edit-family-name" required></label><div class="form-pair"><label>Relationship<input name="relationship" id="edit-family-relationship" required></label><label>Date of birth<input type="date" name="date_of_birth" id="edit-family-dob" max="<?php echo date('Y-m-d');?>"></label></div><div class="form-pair"><label>Gender<select name="gender" id="edit-family-gender"><option value="">Prefer not to say</option><option>Female</option><option>Male</option><option>Other</option></select></label><label>Phone<input name="family_phone" id="edit-family-phone" pattern="[0-9]{10}"></label></div><label>Medical issues or assistance<textarea name="family_medical" id="edit-family-medical" rows="3"></textarea></label><label><span><input type="checkbox" name="is_pwd" id="edit-family-is-pwd" value="1"> Person with disability (PWD)</span></label><label>PWD support details<textarea name="pwd_details" id="edit-family-pwd-details" rows="3" maxlength="500"></textarea></label><div class="profile-dialog-actions"><button type="button" class="dialog-secondary profile-dialog-cancel">Cancel</button><button>Save changes</button></div></form></dialog>
<script>(()=>{const calculateAge=value=>{if(!value)return null;const birth=new Date(value+'T00:00:00');const today=new Date();if(Number.isNaN(birth.getTime())||birth>today)return null;let years=today.getFullYear()-birth.getFullYear();if(today.getMonth()<birth.getMonth()||(today.getMonth()===birth.getMonth()&&today.getDate()<birth.getDate()))years--;return years};const updateAge=input=>{let output=input.parentElement.querySelector('.age-preview');if(!output){output=document.createElement('output');output.className='age-preview';output.setAttribute('aria-live','polite');input.insertAdjacentElement('afterend',output)}const years=calculateAge(input.value);output.textContent=years===null?'':'Age: '+years+' year'+(years===1?'':'s')};document.querySelectorAll('input[name="date_of_birth"]').forEach(input=>{input.addEventListener('input',()=>updateAge(input));input.addEventListener('change',()=>updateAge(input));updateAge(input)});const dialog=document.querySelector('#family-edit-dialog');document.querySelectorAll('.family-edit').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#edit-family-id').value=button.dataset.id;document.querySelector('#edit-family-name').value=button.dataset.name;document.querySelector('#edit-family-relationship').value=button.dataset.relationship;const dob=document.querySelector('#edit-family-dob');dob.value=button.dataset.dob;updateAge(dob);document.querySelector('#edit-family-gender').value=button.dataset.gender;document.querySelector('#edit-family-phone').value=button.dataset.phone;document.querySelector('#edit-family-medical').value=button.dataset.medical;dialog.showModal()}));document.querySelectorAll('.profile-dialog-close,.profile-dialog-cancel').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()})})();</script>
<script>document.querySelectorAll('.family-edit').forEach(button=>button.addEventListener('click',()=>{document.querySelector('#edit-family-is-pwd').checked=button.dataset.isPwd==='1';document.querySelector('#edit-family-pwd-details').value=button.dataset.pwdDetails||''}));</script>
